window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b3916763f7dddc27"]={"versions": [{"id": "FIG-b3916763f7dddc27", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung der Gruppenbeziehung (<code>Group relation</code>) innerhalb der AUTOSAR-Vorlagenarchitektur (Resource Template ECU / Software-Collection-Spezifikation). Das Diagramm stellt die Metamodell-Struktur zur Aggregation, Komposition und Verknüpfung von Software-Kollektionen sowie deren Bezug zu identifizierbaren AUTOSAR-Elementen dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>ARPackage</strong> (<code>&lt;&lt;Namespace&gt;&gt;</code>): Aggregiert über die Komposition <code>+collection</code> 0..1 Exemplare von <code>SW-COLLECTION-SPEC</code>.\n</li><li><strong>SW-COLLECTION-SPEC</strong>: Enthält über die Komposition <code>+collections</code> beliebige viele (<code>*</code>) Instanzen von <code>SW-COLLECTION</code>.\n</li><li><strong>SW-COLLECTION</strong> (kursiv dargestellt, abstrakt):\n<ul class=\"fig-list\"><li>Attribut: <code>+ ROOT: Boolean</code> (rot hervorgehoben).\n</li><li>Assoziiert über <code>+identifiables</code> 0..* Exemplare von <code>Identifiable</code>.\n</li><li>Dient als Ziel von gerichteten Assoziationen (Kardinalität jeweils 1) ausgehend von <code>INCLUDED-SW-COLLECTION</code> und <code>EXCLUDED-SW-COLLECTION</code>.\n</li></ul>\n</li><li><strong>SW-COLLECTION(CONT)</strong>: Spezialisierung von <code>SW-COLLECTION</code> via Generalisierung.\n</li><li><strong>SW-COLLECTION(REF)</strong>: Spezialisierung von <code>SW-COLLECTION</code> via Generalisierung. Aggregiert per Komposition:\n<ul class=\"fig-list\"><li><code>+includedCollections</code> (<code>*</code>): Komposition von <code>INCLUDED-SW-COLLECTION</code>.\n</li><li><code>+excludedCollections</code> (<code>*</code>): Komposition von <code>EXCLUDED-SW-COLLECTION</code>.\n</li></ul>\n</li><li><strong>Identifiable</strong>: Basisklasse mit den Attributen <code>+ shortName: Identifier</code>, <code>+ longName: String [0..1]</code> und <code>+ category: String [0..1]</code>.\n</li><li><strong>SW-COLLECTION-CONT-ELEMENT</strong>: Separierte Entität ohne dargestellte Relationen im Diagrammausschnitt.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne dynamische Interaktions- oder Sequenzabläufe. Die Navigation erfolgt ausgehend vom Paket über die Spezifikation in konkrete Kollektionshierarchien, die über Inklusions- und Exklusionsmechanismen (<code>INCLUDED-SW-COLLECTION</code>, <code>EXCLUDED-SW-COLLECTION</code>) referenzierend oder als eigenständige Container-Struktur auf <code>SW-COLLECTION</code>-Knoten und zugeordnete <code>Identifiable</code>-Elemente verweisen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Metamodell für AUTOSAR ECU-Ressourcenbeschreibungen. Für Modellierer und Werkzeugentwickler ist die Unterscheidung zwischen referenzierender (<code>SW-COLLECTION(REF)</code>) und containerbasierter (<code>SW-COLLECTION(CONT)</code>) Kollektionsbildung bindend. Die Zusammensetzung über Einschluss und Ausschluss erfordert eine eindeutige Auflösung gegen die referenzierte Zielkollektion (Kardinalität 1). Das Attribut <code>ROOT</code> kennzeichnet den Einstiegspunkt des Kollektionsbaums.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-fd6d41d076837a7f", "releases": ["R3.0.7", "R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung der Gruppenbeziehung (<code>Group relation</code>) innerhalb der AUTOSAR-Vorlagenarchitektur (Resource Template ECU / Software-Collection-Spezifikation). Das Diagramm stellt die Metamodell-Struktur zur Aggregation, Komposition und Verknüpfung von Software-Kollektionen sowie deren Bezug zu identifizierbaren AUTOSAR-Elementen dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>ARPackage</strong> (<code>&lt;&lt;Namespace&gt;&gt;</code>): Aggregiert über die Komposition <code>+collection</code> 0..1 Exemplare von <code>SW-COLLECTION-SPEC</code>.\n</li><li><strong>SW-COLLECTION-SPEC</strong>: Enthält über die Komposition <code>+collections</code> beliebige viele (<code>*</code>) Instanzen von <code>SW-COLLECTION</code>.\n</li><li><strong>SW-COLLECTION</strong> (kursiv dargestellt, abstrakt):\n<ul class=\"fig-list\"><li>Attribut: <code>+ ROOT: Boolean</code> (rot hervorgehoben).\n</li><li>Assoziiert über <code>+identifiables</code> 0..* Exemplare von <code>Identifiable</code>.\n</li><li>Dient als Ziel von gerichteten Assoziationen (Kardinalität jeweils 1) ausgehend von <code>INCLUDED-SW-COLLECTION</code> und <code>EXCLUDED-SW-COLLECTION</code>.\n</li></ul>\n</li><li><strong>SW-COLLECTION(CONT)</strong>: Spezialisierung von <code>SW-COLLECTION</code> via Generalisierung.\n</li><li><strong>SW-COLLECTION(REF)</strong>: Spezialisierung von <code>SW-COLLECTION</code> via Generalisierung. Aggregiert per Komposition:\n<ul class=\"fig-list\"><li><code>+includedCollections</code> (<code>*</code>): Komposition von <code>INCLUDED-SW-COLLECTION</code>.\n</li><li><code>+excludedCollections</code> (<code>*</code>): Komposition von <code>EXCLUDED-SW-COLLECTION</code>.\n</li></ul>\n</li><li><strong>Identifiable</strong>: Basisklasse mit den Attributen <code>+ shortName: Identifier</code>, <code>+ longName: String [0..1]</code> und <code>+ category: String [0..1]</code>.\n</li><li><strong>SW-COLLECTION-CONT-ELEMENT</strong>: Separierte Entität ohne dargestellte Relationen im Diagrammausschnitt.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne dynamische Interaktions- oder Sequenzabläufe. Die Navigation erfolgt ausgehend vom Paket über die Spezifikation in konkrete Kollektionshierarchien, die über Inklusions- und Exklusionsmechanismen (<code>INCLUDED-SW-COLLECTION</code>, <code>EXCLUDED-SW-COLLECTION</code>) referenzierend oder als eigenständige Container-Struktur auf <code>SW-COLLECTION</code>-Knoten und zugeordnete <code>Identifiable</code>-Elemente verweisen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Metamodell für AUTOSAR ECU-Ressourcenbeschreibungen. Für Modellierer und Werkzeugentwickler ist die Unterscheidung zwischen referenzierender (<code>SW-COLLECTION(REF)</code>) und containerbasierter (<code>SW-COLLECTION(CONT)</code>) Kollektionsbildung bindend. Die Zusammensetzung über Einschluss und Ausschluss erfordert eine eindeutige Auflösung gegen die referenzierte Zielkollektion (Kardinalität 1). Das Attribut <code>ROOT</code> kennzeichnet den Einstiegspunkt des Kollektionsbaums.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-b3916763f7dddc27", "to": "FIG-fd6d41d076837a7f", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
